public void command(final Contact contact, final MessageIrcImpl message) throws UnsupportedCommandException, BadCommandException, BadCommandInvocationException {
  if (!this.connectionState.isConnected()) {
    throw new IllegalStateException("Not connected to IRC server.");
  }
  try {
    command(contact.getAddress(), message.getContent());
  } catch (ClassCastException | IndexOutOfBoundsException e) {
    // Handle the runtime exceptions, e.g., log the error or take corrective action
    e.printStackTrace();
  }
}
